paragraph.math:
$$\begin{array}{l}
  {{\lbrack D(x_{1}) - \overline{p}\rbrack\Delta x + \lbrack D(x_{2}) - \overline{p}\rbrack\Delta x + \cdots + \lbrack D(x_{n}) - \overline{p}\rbrack\Delta x} = \lbrack D(x_{1}) + D(x_{2}) + \cdots + D(x_{n})\rbrack\Delta x - \underset{n{terms}}{\underset{︸}{\lbrack\overline{p}\Delta x + \overline{p}\Delta x + \cdots + \overline{p}\Delta x\rbrack}}} \\
  {\phantom{\lbrack D(x_{1}) - \overline{p}\rbrack\Delta x + \lbrack D(x_{2}) - \overline{p}\rbrack\Delta x + \cdots + \lbrack D(x_{n}) - \overline{p}\rbrack\Delta x}{= \lbrack D(x_{1}) + D(x_{2}) + \cdots + D(x_{n})\rbrack\Delta x - n\overline{p}\Delta x}} \\
  {\phantom{\lbrack D(x_{1}) - \overline{p}\rbrack\Delta x + \lbrack D(x_{2}) - \overline{p}\rbrack\Delta x + \cdots + \lbrack D(x_{n}) - \overline{p}\rbrack\Delta x}{= \lbrack D(x_{1}) + D(x_{2}) + \cdots + D(x_{n})\rbrack\Delta x - \overline{p}\overline{x}}}
  \end{array}$$

$$\begin{array}{ccl}
  {R(t)} & = & {{{Rate\ of\ income\ generation\ at\ any\ time}t}\qquad{In\ dollars\ per\ year}} \\
  {r} & = & {Interest\ rate\ compounded\ continuously} \\
  T & = & {{Term}\qquad{In\ years}}
  \end{array}$$

$$\begin{array}{lcl}
  P & = & {Size\ of\ each\ payment\ in\ the\ annuity} \\
  r & = & {Interest\ rate\ compounded\ continuously} \\
  T & = & {{Term\ of\ the\ annuity}({in\ years})} \\
  m & = & {Number\ of\ payments\ per\ year}
  \end{array}$$

$$\begin{array}{l}
  {A{= e^{\mathit{rT}}\int_{0}^{T}{R(t)e^{- rt}dt = e^{\mathit{rT}}\int_{0}^{T}{mPe^{- rt}dt}}}} \\
  {\phantom{A}{= mPe^{\mathit{rT}}{\left\lbrack {- \frac{e^{- rt}}{r}} \right\rbrack|}_{0}^{T} = mPe^{\mathit{rT}}\left\lbrack {- \frac{e^{- rT}}{r} + \frac{1}{r}} \right\rbrack}} \\
  {\phantom{A}{= \frac{\mathit{mP}}{r}\left( {e^{\mathit{rT}} - 1} \right)\qquad{{Since}e^{rT} \cdot e^{- rT} = 1}}}
  \end{array}$$
